#include <FastLED.h>

#define STRIP_LEN    30
#define N_ORANGE     8
#define N_BLUE       2

const uint8_t pinOrange[N_ORANGE] = {2,3,4,5,6,7,8,9};
const uint8_t pinBlue[N_BLUE]     = {10,11};
const uint8_t pinSound = A0;

const CRGB softOrange(255, 140, 25);
const CRGB brightGold(255, 215, 0);

CRGB bufOrange[N_ORANGE * STRIP_LEN];
CRGB bufBlue[N_BLUE * STRIP_LEN];

float wavePhase = 0.0f;
float runnerPos[N_BLUE] = {0.0f, 15.0f};

uint8_t curBright = 180;
unsigned long prevMs = 0;

void setup() {
  FastLED.addLeds<WS2812B,  2, GRB>(bufOrange,  0 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  3, GRB>(bufOrange,  1 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  4, GRB>(bufOrange,  2 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  5, GRB>(bufOrange,  3 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  6, GRB>(bufOrange,  4 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  7, GRB>(bufOrange,  5 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  8, GRB>(bufOrange,  6 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B,  9, GRB>(bufOrange,  7 * STRIP_LEN, STRIP_LEN);

  FastLED.addLeds<WS2812B, 10, GRB>(bufBlue, 0 * STRIP_LEN, STRIP_LEN);
  FastLED.addLeds<WS2812B, 11, GRB>(bufBlue, 1 * STRIP_LEN, STRIP_LEN);

  FastLED.setBrightness(curBright);
  FastLED.clear();
  FastLED.show();
  prevMs = millis();
}

void loop() {
  unsigned long now = millis();
  float dt = (now - prevMs) / 1000.0f;
  prevMs = now;
  if (dt > 0.1f) dt = 0.1f;

  int sound = analogRead(pinSound);
  uint8_t target = (sound > 80) ? 255 : 180;
  if (curBright < target) curBright++;
  else if (curBright > target) curBright--;
  FastLED.setBrightness(curBright);

  wavePhase += (TWO_PI / 300.0f) * dt;
  if (wavePhase > TWO_PI) wavePhase -= TWO_PI;

  for (int s = 0; s < N_ORANGE; s++) {
    float segPhase = wavePhase + (float)s / N_ORANGE * TWO_PI;
    float mix = (sin(segPhase) + 1.0f) * 0.5f;
    CRGB color = blend(softOrange, brightGold, (uint8_t)(mix * 255.0f));
    for (int p = 0; p < STRIP_LEN; p++) {
      bufOrange[s * STRIP_LEN + p] = color;
    }
  }

  for (int s = 0; s < N_BLUE; s++) {
    runnerPos[s] += 30.0f * dt;
    if (runnerPos[s] >= STRIP_LEN) runnerPos[s] -= STRIP_LEN;

    fill_solid(&bufBlue[s * STRIP_LEN], STRIP_LEN, CRGB::Black);

    int p1 = (int)runnerPos[s] % STRIP_LEN;
    int p2 = (int)(runnerPos[s] + STRIP_LEN / 2) % STRIP_LEN;

    bufBlue[s * STRIP_LEN + p1] = CRGB(0, 150, 255);
    bufBlue[s * STRIP_LEN + p2] = CRGB(0, 150, 255);

    for (int t = 1; t <= 4; t++) {
      int tp = (p1 - t + STRIP_LEN) % STRIP_LEN;
      bufBlue[s * STRIP_LEN + tp] = CRGB(0, max(0, 150 - t * 35), max(0, 255 - t * 25));
      tp = (p2 - t + STRIP_LEN) % STRIP_LEN;
      bufBlue[s * STRIP_LEN + tp] = CRGB(0, max(0, 150 - t * 35), max(0, 255 - t * 25));
    }
  }

  FastLED.show();
  delay(12);
}
